INSERT INTO `pricing_notes` (`id`, `category`, `sort_order`, `title`, `body`, `created_at`, `updated_at`) VALUES
(1, 'passenger_general', 10, 'Ghi chú xe hành khách', 'Giá đã bao gồm phí cầu đường, phí bến bãi, VAT 8%. Giá xe tính từ Thứ 2 - Thứ 6; Thứ 7 - Chủ nhật phụ thu 30%. Xe 45 chỗ không đi được tuyến vườn trường Hóc Môn.', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(2, 'passenger_driver', 20, 'Tài xế ăn ngủ', 'Tài xế ăn ngủ theo đoàn nếu xe đi tỉnh. Nếu tài xế ăn ngủ tự túc: phụ thu 540.000đ/người/2N1Đ (đã bao gồm 8% VAT). Cột \"Chi phí tự túc TX\" trong bảng giá: 540.000đ.', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(3, 'passenger_cancel', 30, 'Huỷ xe trước ngày thực hiện — báo hợp lệ', 'Có thông báo trước tối thiểu 12 giờ làm việc: không tính phí.', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(4, 'passenger_cancel', 40, 'Huỷ xe trước ngày thực hiện — báo muộn', 'Dưới 12 giờ làm việc: 50% giá trị chuyến xe (đã chốt lịch nhưng chưa điều xe).', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(5, 'passenger_cancel', 50, 'Huỷ khi đã điều xe đến điểm đón', 'Xe đã di chuyển hoặc có mặt tại điểm đón: 70% giá trị chuyến xe (tính theo thực tế điều động).', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(6, 'passenger_cancel', 60, 'Huỷ do bất khả kháng', 'Có chứng minh bằng văn bản hoặc thông tin xác nhận: hai bên cùng rà soát, không tính phí (ví dụ thiên tai, sự cố bất ngờ, quyết định hành chính).', '2026-06-21 04:50:26', '2026-06-21 04:50:26'),
(7, 'cargo_general', 10, 'Ghi chú xe hàng hóa', 'Đơn giá một chiều, đã bao gồm VAT. Hỗ trợ bốc xếp: hàng 10-20 kiện — 1 người tại 1 điểm lấy hàng 100.000 VNĐ; bốc xếp 2 đầu 200.000 VNĐ. Phí chờ: 60.000 VNĐ/giờ đối với hàng từ 20 kiện hoặc 100kg trở lên. Lộ trình không có trong bảng: liên hệ NV điều vận.', '2026-06-21 04:50:26', '2026-06-21 04:50:26');
